#!/usr/bin/env node
/**
 * Mirrors the generated Encore client from the web workspace into the mobile app.
 *
 * The client is generated by `encore gen client --target leap` and written to
 * frontend/client.ts. It is plain fetch-based TypeScript and runs unchanged on
 * Hermes with one exception: the trailing default export reads `import.meta.env`,
 * which does not exist in React Native. We strip that default export — the mobile
 * app always constructs the client explicitly through `useBackend()`.
 *
 * Run after every `encore gen client` so the mobile app stays in sync with the API.
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const source = resolve(here, '../../frontend/client.ts');
const target = resolve(here, '../src/api/client.ts');

const banner = `/* eslint-disable */
// AUTO-GENERATED — DO NOT EDIT.
// Mirrored from frontend/client.ts by \`bun run sync-client\`.
// Regenerate the source with: cd backend && encore gen client --target leap
`;

let code = readFileSync(source, 'utf8');

// React Native has no import.meta; the default-export singleton is web-only.
const defaultExportPattern = /^export default new Client\(import\.meta\.env[^\n]*\n?/m;
if (!defaultExportPattern.test(code)) {
  console.warn('[sync-client] No import.meta default export found — assuming already RN-safe.');
} else {
  code = code.replace(
    defaultExportPattern,
    '// (web-only default export removed — the mobile app builds the Client in src/api/backend.ts)\n'
  );
}

if (/import\.meta/.test(code)) {
  console.error('[sync-client] FAILED: client still references import.meta after patching.');
  process.exit(1);
}

/**
 * Cut the dependency on the `encore.dev` server package.
 *
 * The generated client imports a handful of types from it. Those types are pure
 * shapes — but resolving them drags the backend framework's TypeScript *source*
 * into the app's typecheck (and would drag it into the bundle graph if anything
 * ever imported a value). A mobile app that ships to devices must not depend on
 * the server framework, so we inline structurally-identical local declarations.
 */
const encoreShim = `
// ── Local stand-ins for the \`encore.dev/api\` types the generated client
// references. Structurally identical in arity; declared here so the mobile app
// does not depend on the backend framework package. The stream handlers take
// <Handshake, Req, Resp> — matching how StreamRequest/StreamResponse below
// destructure them.
type CookieWithOptions<T = unknown> = { value: T; [option: string]: unknown };
type StreamInOutHandlerFn<Handshake, Req, Resp> = (handshake: Handshake, req: Req) => AsyncGenerator<Resp>;
type StreamInHandlerFn<Handshake, Req, Resp> = (handshake: Handshake, req: Req) => Promise<Resp>;
type StreamOutHandlerFn<Handshake, Resp> = (handshake: Handshake) => AsyncGenerator<Resp>;
`;

const typeImport = /^import type \{ CookieWithOptions \} from "encore\.dev\/api";\n/m;
const valueImport = /^import \{\n(?:\s+Stream\w+HandlerFn,\n)+\} from "encore\.dev\/api";\n/m;

if (!typeImport.test(code)) {
  console.warn('[sync-client] encore.dev type import not found — shape may have changed.');
}

code = code.replace(typeImport, encoreShim.trimStart());
code = code.replace(valueImport, '');

if (/from "encore\.dev/.test(code)) {
  console.error('[sync-client] FAILED: client still imports from encore.dev after patching.');
  process.exit(1);
}

/**
 * Relax the endpoint payload helpers.
 *
 * `RequestType`/`ResponseType` derive their shapes from the backend handler
 * signatures imported through `~backend/*`. The mobile app resolves those
 * specifiers to `any` (see src/api/backend-modules.d.ts for the full rationale),
 * which makes `Parameters<any>` fall through to `void` — every endpoint would
 * then reject its own arguments.
 *
 * Widening both helpers to `any` keeps the endpoint *names* precisely typed
 * while letting payloads through. Domain shapes are still checked at the call
 * sites via the mirrored types in src/types/.
 */
const requestTypeDefinition =
  /type RequestType<Type extends \(\.\.\.args: any\[\]\) => any> =\s*\n\s*Parameters<Type> extends \[infer H, \.\.\.any\[\]\]\s*\n\s*\? OmitCookie<H>\s*\n\s*: void;/;
const responseTypeDefinition =
  /type ResponseType<Type extends \(\.\.\.args: any\[\]\) => any> = OmitCookie<Awaited<ReturnType<Type>>>;/;

const relaxedHelpers = [
  '// Widened by scripts/sync-backend-client.mjs — see src/api/backend-modules.d.ts.',
  '// The backend handler signatures these derive from are not resolvable in the app.',
  'type RequestType<Type extends (...args: any[]) => any> = any;',
  '',
  'type ResponseType<Type extends (...args: any[]) => any> = any;',
].join('\n');

if (!requestTypeDefinition.test(code) || !responseTypeDefinition.test(code)) {
  console.error('[sync-client] FAILED: RequestType/ResponseType helpers not found — generator output changed.');
  process.exit(1);
}

code = code.replace(requestTypeDefinition, relaxedHelpers).replace(responseTypeDefinition, '');

/**
 * Annotate the generator's untyped query-array callbacks.
 *
 * The generator emits `params.foo?.map((v) => v)` for array query params. That
 * relied on `params` being precisely typed; now that it is `any`, `v` trips
 * `noImplicitAny`. Rather than disabling strictness for the whole file (which
 * would hide genuine breakage in a file we re-sync regularly), annotate the
 * callback and assert the occurrence count so a generator change is noticed.
 */
const untypedMapCallbacks = code.match(/\.map\(\(v\) => v\)/g) ?? [];
if (untypedMapCallbacks.length > 0) {
  code = code.replace(/\.map\(\(v\) => v\)/g, '.map((v: string) => v)');
  console.log(`[sync-client] Annotated ${untypedMapCallbacks.length} query-array callback(s)`);
}

mkdirSync(dirname(target), { recursive: true });
writeFileSync(target, banner + code, 'utf8');
console.log(`[sync-client] Wrote ${target} (${(code.length / 1024).toFixed(0)} KB)`);
